// A PR body must not carry the tooling-appended "Generated by Claude Code" footer (ADR-0017 §10, CONTRIBUTORS.md).
// The body is read from the PR_BODY environment variable, never from the command line or an inline interpolation:
// a PR body is attacker-controlled text and must not reach a shell.
import { fileURLToPath } from 'node:url'

// The ADR names `_Generated by [Claude Code](…)_`; the same tool also emits "Generated with [Claude Code](…)", so
// both verbs are matched, with or without the markdown link brackets.
const FOOTER = /generated\s+(?:by|with)\s+\[?\s*claude\s+code/i

/** Returns the offending footer line of a PR body, or null when the body is clean. */
export function findFooter(body) {
  if (typeof body !== 'string') return null
  return body.split(/\r?\n/).find((line) => FOOTER.test(line))?.trim() ?? null
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const hit = findFooter(process.env.PR_BODY ?? '')
  if (hit) {
    console.error(`pr-body-footer-check: the PR body carries a tool-attribution footer (ADR-0017 §10):\n  ${hit}\nRewrite the PR body without it.`)
    process.exit(1)
  }
  console.log('pr-body-footer-check: PR body carries no tool-attribution footer')
}
